set-variable.value:
@{
                Func<JToken, string> text = c => {
                  if (c == null) return "";
                  if (c.Type == JTokenType.String) return (string)c;
                  var sb = new System.Text.StringBuilder();
                  var arr = c as JArray;
                  if (arr != null) { foreach (var p in arr) { var t = p["text"]; if (t != null && t.Type == JTokenType.String) { sb.Append((string)t).Append("\n"); } } }
                  return sb.ToString();
                };

                try {
                  var b = context.Response.Body.As<JObject>(preserveContent: true);
                  var ch = b["choices"] as JArray;
                  if (ch == null) return "";
                  var sb = new System.Text.StringBuilder();
                  foreach (var c in ch) { var m = c["message"]; if (m != null) { sb.Append(text(m["content"])).Append("\n"); } }
                  string u = sb.ToString();
                  if (u.Trim().Length == 0) return "";
                  if (u.Length > 10000) { u = u.Substring(0, 10000); }
                  return new JObject(new JProperty("text", u), new JProperty("categories", new JArray("Hate", "SelfHarm", "Sexual", "Violence")), new JProperty("outputType", "FourSeverityLevels")).ToString(Newtonsoft.Json.Formatting.None);
                } catch (Exception) { return ""; }
                }

@{
                        try {
                          var r = (IResponse)context.Variables["rp-out-resp"];
                          if (r == null) return "dependency";
                          int s = r.StatusCode;
                          if (s == 200) {
                            var j = r.Body.As<JObject>();
                            var allowed = new string[] { "Hate", "SelfHarm", "Sexual", "Violence" };
                            string cat = ""; int sev = 0;
                            var items = j["categoriesAnalysis"] as JArray;
                            if (items != null) {
                              foreach (var i in items) {
                                string c = (string)i["category"]; var sv = i["severity"];
                                if (c != null && Array.IndexOf(allowed, c) >= 0 && sv != null && sv.Type == JTokenType.Integer && (int)sv > sev) { cat = c; sev = (int)sv; }
                              }
                            }
                            return "ok:" + cat + ":" + sev.ToString();
                          }
                          if (s == 401 || s == 403) return "auth";
                          if (s == 408 || s == 429 || s >= 500) return "dependency";
                          return "config";
                        } catch (Exception) { return "dependency"; }
                        }

@{
                        string a = (string)context.Variables["rp-out-result"];
                        bool over = a.StartsWith("ok:") && int.Parse(a.Split(':')[2]) >= {severity-threshold};
                        if (over) return "block";
                        if (!context.Variables.ContainsKey("rp-cs-token") || a == "auth" || a == "config") return "error";
                        if (a == "dependency") { return ((string)context.Variables["rp-safety-mode"]) == "regulated" ? "error" : "allowed_on_safety_error"; }
                        return "allow";
                        }

@{
                        string o = (string)context.Variables["rp-out-decision"];
                        string i = (string)context.Variables["rp-safety-decision"];
                        return (o != "allow" || i == "allow") ? "output" : (string)context.Variables["rp-safety-phase"];
                        }

@{
                        string a = (string)context.Variables["rp-out-result"];
                        if ((string)context.Variables["rp-safety-phase"] != "output" || !a.StartsWith("ok:")) return (string)context.Variables["rp-safety-category"];
                        return a.Split(':')[1];
                        }

@{
                        string a = (string)context.Variables["rp-out-result"];
                        if ((string)context.Variables["rp-safety-phase"] != "output" || !a.StartsWith("ok:")) return (string)context.Variables["rp-safety-severity"];
                        return a.Split(':')[2];
                        }

@{
                        string o = (string)context.Variables["rp-out-decision"];
                        string i = (string)context.Variables["rp-safety-decision"];
                        if (o == "block" || o == "error") return o;
                        if (o == "allowed_on_safety_error" || i == "allowed_on_safety_error") return "allowed_on_safety_error";
                        return "allow";
                        }
